function maxA(n) {
  // layers[p] maps a clipboard size to the largest screen reachable with exactly p presses;
  // for the same presses and clipboard, a longer screen is never worse.
  const layers = Array.from({ length: n + 1 }, () => new Map());
  layers[0].set(0, 0);
  let answer = 0;
  const offer = (p, clip, screen) => {
    if (p <= n && (layers[p].has(clip) ? layers[p].get(clip) : -1) < screen) layers[p].set(clip, screen);
  };
  for (let p = 0; p <= n; p++) {
    for (const [clip, screen] of layers[p]) {
      answer = Math.max(answer, screen);
      offer(p + 1, clip, screen + 1);
      if (clip > 0) offer(p + 1, clip, screen + clip);
      // Ctrl-A then Ctrl-C: two presses that load the whole screen into the clipboard.
      offer(p + 2, screen, screen);
    }
  }
  return answer;
}

